function procurementGuard5(q){const p=state.procurement5;if(p.orders.filter(o=>o.received===null).length>=40)throw Error('Nejvýše 40 dodavatelských zásilek na cestě.');if(q.kg>q.capacity)throw Error('Dodavatel už tento týden nemá dost volné kapacity.');if(q.terms&&(state.departments.finance<1||!state.stores.length))throw Error('Splatnost vyžaduje vlastní kavárnu a obsazené Finance.');if(q.terms&&p.payables.some(x=>x.supplier===q.supplier&&x.paid===null&&x.due<=state.week))throw Error('Nejprve uhraď splatné faktury tohoto dodavatele.');if(q.terms&&procurementCredit5()+q.cost>300000)throw Error('Dodavatelský úvěr včetně zásilek má limit 300 000 Kč.');const due=p.payables.filter(x=>x.paid===null&&x.due<=state.week+2).reduce((n,x)=>n+x.amount,0);if(state.cash-(q.terms?0:q.cost)-q.fee-due<weeklyFixed()*q.reserve)throw Error('Objednávka by porušila rezervu včetně blízkých splatných závazků.');}
