function previewProcurement5(action,weeks=4){if(![4,8].includes(weeks)||!action||!['order','contract'].includes(action.kind))throw Error('Vyber objednávku nebo odběr a 4 či 8 týdnů.');if(!state.stores.length)throw Error('Pro výhled nejprve otevři kavárnu.');const original=state,run=change=>{state=JSON.parse(JSON.stringify(original));if(change){if(action.kind==='order')buyProcurement5(action.data);else signProcurement5(action.data);}const series=[];for(let i=0;i<weeks&&!state.over;i++){const h=nextWeek(),rows=state.procurement5.history.at(-1).rows;series.push({week:h.week,cash:state.cash,profit:h.profit,payables:procurementPayable5(),received:rows.reduce((n,r)=>n+r.received,0),paid:rows.reduce((n,r)=>n+r.paid,0),lost:state.supply5.last.cities.reduce((n,c)=>n+c.lost,0)});}return {series,over:state.over};};try{return {week:original.week,weeks,baseline:run(false),changed:run(true)};}finally{state=original;}}
